public static void main(Args _args)
{
    METCancelSalesOrdersController controller;
    try
    {
        controller = new METCancelSalesOrdersController(classStr(METCancelSalesOrderService), methodStr(METCancelSalesOrderService,process), SysOperationExecutionMode::ScheduledBatch);
        controller.parmArgs(_args);
        controller.parmShowDialog(true);
        controller.startOperation();
    }
    catch (Exception::Error)
    {
        error("@MET:CancelOrderError");
    }
}

